/**
 * Generates shared/campuses.ts (the campus list bundled into the app) from data/campuses.csv.
 *
 *   npx tsx scripts/generate-campuses.ts          # rewrites shared/campuses.ts
 *
 * data/campuses.csv (header: name,city) is the single source. The file is also generated by `prebuild`.
 * Ids are stable: same name and city always give the same id, so already-saved profiles keep resolving.
 */
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { checkCampusInput, normalizeCampusText } from '../shared/campus.ts';

export interface CampusCsvRow {
  name: string;
  city: string;
}

/** Minimal RFC 4180 parser: quoted fields, escaped quotes (""), commas and newlines inside quotes. */
export function parseCsv(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = '';
  let inQuotes = false;
  const src = text.replace(/^\uFEFF/, '');
  for (let i = 0; i < src.length; i++) {
    const ch = src[i]!;
    if (inQuotes) {
      if (ch === '"') {
        if (src[i + 1] === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += ch;
      }
    } else if (ch === '"') {
      inQuotes = true;
    } else if (ch === ',') {
      row.push(field);
      field = '';
    } else if (ch === '\n' || ch === '\r') {
      if (ch === '\r' && src[i + 1] === '\n') i++;
      row.push(field);
      field = '';
      if (row.some((c) => c.trim() !== '')) rows.push(row);
      row = [];
    } else {
      field += ch;
    }
  }
  row.push(field);
  if (row.some((c) => c.trim() !== '')) rows.push(row);
  return rows;
}

/** Parses and validates the campus CSV. Throws one error listing every bad line. */
export function parseCampusCsv(text: string): CampusCsvRow[] {
  const rows = parseCsv(text);
  const header = (rows[0] ?? []).map((c) => c.trim().toLowerCase());
  if (header[0] !== 'name' || header[1] !== 'city' || header.length !== 2) {
    throw new Error('CSV header must be exactly: name,city');
  }

  const problems: string[] = [];
  const out: CampusCsvRow[] = [];
  const seen = new Set<string>();
  rows.slice(1).forEach((cells, idx) => {
    const line = idx + 2;
    if (cells.length !== 2) {
      problems.push(`line ${line}: expected 2 columns, got ${cells.length}`);
      return;
    }
    const checked = checkCampusInput(cells[0], cells[1]);
    if (!checked.ok) {
      problems.push(`line ${line}: ${checked.error}`);
      return;
    }
    const key = `${normalizeCampusText(checked.name)}|${normalizeCampusText(checked.city)}`;
    if (seen.has(key)) return;
    seen.add(key);
    out.push({ name: checked.name, city: checked.city });
  });

  if (problems.length > 0) throw new Error(`Invalid campus CSV:\n${problems.join('\n')}`);
  return out;
}

/** Same name and city always give the same id, so re-seeding never duplicates a campus. */
export function campusId(name: string, city: string): string {
  const digest = createHash('sha256').update(`${normalizeCampusText(name)}|${normalizeCampusText(city)}`).digest('hex');
  return `cmp_${digest.slice(0, 24)}`;
}

/** Source text of shared/campuses.ts for the given rows (sorted by city, then name). */
export function buildCampusModule(rows: CampusCsvRow[]): string {
  const sorted = [...rows].sort((a, b) => a.city.localeCompare(b.city) || a.name.localeCompare(b.name));
  const items = sorted
    .map((r) => `  { id: ${JSON.stringify(campusId(r.name, r.city))}, name: ${JSON.stringify(r.name)}, city: ${JSON.stringify(r.city)} },`)
    .join('\n');
  return `// GENERATED by scripts/generate-campuses.ts from data/campuses.csv. Do not edit by hand.
export interface BundledCampus {
  readonly id: string;
  readonly name: string;
  readonly city: string;
}

export const CAMPUSES: readonly BundledCampus[] = [
${items}
];
`;
}

const isMain = process.argv[1] ? fileURLToPath(import.meta.url) === process.argv[1] : false;
if (isMain) {
  try {
    const rows = parseCampusCsv(readFileSync(new URL('../data/campuses.csv', import.meta.url), 'utf8'));
    if (rows.length === 0) throw new Error('data/campuses.csv has no rows under the "name,city" header');
    writeFileSync(new URL('../shared/campuses.ts', import.meta.url), buildCampusModule(rows));
    console.log(`shared/campuses.ts: ${rows.length} campuses`);
  } catch (err) {
    console.error((err as Error).message);
    process.exit(1);
  }
}
